const cfg = $('Campaign configuration').first().json;
const payload = $input.first().json;
const feed = Array.isArray(payload) ? {campaigns:payload} : payload;
if (!Array.isArray(feed.campaigns)) throw new Error('Campaign endpoint must return { campaigns: [...] }.');
let day = Number(cfg.campaign_day);
if (cfg.launch_date) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(cfg.launch_date)) throw new Error('launch_date must be UTC YYYY-MM-DD.');
  const start = Date.parse(cfg.launch_date+'T00:00:00Z');
  if (!Number.isFinite(start)) throw new Error('Invalid launch_date.');
  const today = Date.parse(new Date().toISOString().slice(0,10)+'T00:00:00Z');
  day = Math.floor((today-start)/86400000)+1;
}
if (!Number.isInteger(day)) throw new Error('campaign_day must be an integer.');
if (day < 1 || day > 30) return [];
const candidates = feed.campaigns.filter(c => c.day===day && cfg.selected_locales.includes(c.locale) && cfg.selected_variants.includes(c.variant) && cfg.selected_channels.includes(c.channel));
if (!candidates.length) throw new Error('No campaign candidates match this selection.');
return candidates.map(c => ({json:{
  kind:'publication_draft', mode:cfg.live_enabled?'pending_live_review':'draft',
  campaign_id:c.id, day:c.day, locale:c.locale, variant:c.variant, channel:c.channel,
  hook:c.hook, video_script:c.video_script, caption:c.caption, cta:c.cta,
  landing_url:c.utm_link, target_duration_seconds:c.target_duration_seconds,
  visual_beats:c.visual_beats, format:c.format,
  asset_url:cfg.final_asset_urls[c.id] || null,
  idempotency_key:'numerologic:'+c.id,
  requires:['rendered_video','voiceover_timing_check','subtitle_check','channel_and_account_review','explicit_campaign_approval'],
  publication_status:'not_sent'
}}));

const cfg = $('Campaign configuration').first().json;
if (cfg.live_enabled !== true) throw new Error('Live mode is disabled.');
if (cfg.mode !== 'live') throw new Error('Set mode to live explicitly after review.');
if (!/^https:\/\//.test(cfg.adapter_url)) throw new Error('Set your verified HTTPS adapter_url.');
if (cfg.adapter_authorization_configured !== true) throw new Error('Connect the HTTP Header Auth credential to the adapter node first.');
return $input.all().map(item => {
  const d = item.json;
  if (!cfg.approved_channels.includes(d.channel)) throw new Error('Channel is not explicitly approved: '+d.channel);
  if (!cfg.approved_campaign_ids.includes(d.campaign_id)) throw new Error('Campaign is not explicitly approved: '+d.campaign_id);
  if (!/^https:\/\//.test(d.asset_url || '')) throw new Error('Provide a reviewed HTTPS video asset URL for '+d.campaign_id);
  return {json:{...d, mode:'live', adapter_url:cfg.adapter_url,
    adapter_payload:{version:1, action:'prepare_or_publish',campaign_id:d.campaign_id,
      idempotency_key:d.idempotency_key,channel:d.channel,locale:d.locale,
      asset_url:d.asset_url,caption:d.caption,landing_url:d.landing_url,
      approval:{approved:true,campaign_id:d.campaign_id},dry_run:false}}};
});
